19	## PagingSource Implementation
20	
21	```kotlin
22	class ArticlePagingSource(
23	    private val api: ArticleApi,
24	    private val query: String
25	) : PagingSource<Int, Article>() {
26	
27	    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, Article> {
28	        val page = params.key ?: 1
29	        return try {
30	            val response = api.searchArticles(
31	                query = query,
32	                page = page,
33	                pageSize = params.loadSize
34	            )
35	            LoadResult.Page(
36	                data = response.articles,
37	                prevKey = if (page == 1) null else page - 1,
38	                nextKey = if (response.articles.isEmpty()) null else page + 1
39	            )
40	        } catch (e: IOException) {
41	            LoadResult.Error(e)
42	        } catch (e: HttpException) {
43	            LoadResult.Error(e)
44	        }
45	    }
46	
47	    override fun getRefreshKey(state: PagingState<Int, Article>): Int? {
48	        return state.anchorPosition?.let { anchor ->
49	            state.closestPageToPosition(anchor)?.prevKey?.plus(1)
50	                ?: state.closestPageToPosition(anchor)?.nextKey?.minus(1)
51	        }
52	    }
53	}
54	```
