56	## Cursor-Based PagingSource
57	
58	```kotlin
59	class CursorArticlePagingSource(
60	    private val api: ArticleApi
61	) : PagingSource<String, Article>() {
62	
63	    override suspend fun load(params: LoadParams<String>): LoadResult<String, Article> {
64	        return try {
65	            val response = api.getArticles(
66	                cursor = params.key,
67	                limit = params.loadSize
68	            )
69	            LoadResult.Page(
70	                data = response.articles,
71	                prevKey = null, // cursor-based usually does not support backward
72	                nextKey = response.nextCursor
73	            )
74	        } catch (e: Exception) {
75	            LoadResult.Error(e)
76	        }
77	    }
78	
79	    override fun getRefreshKey(state: PagingState<String, Article>): String? = null
80	}
81	```
