126	## Collecting as LazyPagingItems in Compose
127	
128	```kotlin
129	@Composable
130	fun ArticleListScreen(viewModel: ArticleListViewModel = koinViewModel()) {
131	    val articles = viewModel.articles.collectAsLazyPagingItems()
132	
133	    LazyColumn {
134	        items(
135	            count = articles.itemCount,
136	            key = articles.itemKey { it.id }
137	        ) { index ->
138	            val article = articles[index]
139	            if (article != null) {
140	                ArticleCard(article = article)
141	            } else {
142	                ArticlePlaceholder()
143	            }
144	        }
145	
146	        // Append loading indicator
147	        when (articles.loadState.append) {
148	            is LoadState.Loading -> {
149	                item { LoadingIndicator() }
150	            }
151	            is LoadState.Error -> {
152	                item {
153	                    RetryButton(onClick = { articles.retry() })
154	                }
155	            }
156	            else -> {}
157	        }
158	    }
159	}
