162	## Load State Handling
163	
164	```kotlin
165	@Composable
166	fun PaginatedList(articles: LazyPagingItems<Article>) {
167	    Box(modifier = Modifier.fillMaxSize()) {
168	        // Initial loading state
169	        when (articles.loadState.refresh) {
170	            is LoadState.Loading -> {
171	                CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
172	            }
173	            is LoadState.Error -> {
174	                val error = (articles.loadState.refresh as LoadState.Error).error
175	                ErrorScreen(
176	                    message = error.localizedMessage ?: "Unknown error",
177	                    onRetry = { articles.refresh() }
178	                )
179	            }
180	            is LoadState.NotLoading -> {
181	                if (articles.itemCount == 0) {
182	                    EmptyState(message = "No articles found")
183	                } else {
184	                    ArticleLazyColumn(articles = articles)
185	                }
186	            }
187	        }
188	
189	        // Pull to refresh
190	        PullToRefreshBox(
191	            isRefreshing = articles.loadState.refresh is LoadState.Loading,
192	            onRefresh = { articles.refresh() }
193	        ) {
194	            ArticleLazyColumn(articles = articles)
195	        }
196	    }
197	}
