200	## RemoteMediator (Network + Database)
201	
202	```kotlin
203	@OptIn(ExperimentalPagingApi::class)
204	class ArticleRemoteMediator(
205	    private val api: ArticleApi,
206	    private val database: AppDatabase
207	) : RemoteMediator<Int, ArticleEntity>() {
208	
209	    private val articleDao = database.articleDao()
210	    private val remoteKeyDao = database.remoteKeyDao()
211	
212	    override suspend fun load(
213	        loadType: LoadType,
214	        state: PagingState<Int, ArticleEntity>
215	    ): MediatorResult {
216	        val page = when (loadType) {
217	            LoadType.REFRESH -> 1
218	            LoadType.PREPEND -> return MediatorResult.Success(endOfPaginationReached = true)
219	            LoadType.APPEND -> {
220	                val remoteKey = remoteKeyDao.getRemoteKey("articles")
221	                remoteKey?.nextPage ?: return MediatorResult.Success(
222	                    endOfPaginationReached = true
223	                )
224	            }
225	        }
226	
227	        return try {
228	            val response = api.getArticles(page = page, pageSize = state.config.pageSize)
229	
230	            database.withTransaction {
231	                if (loadType == LoadType.REFRESH) {
232	                    articleDao.deleteAll()
233	                    remoteKeyDao.deleteByKey("articles")
234	                }
235	                articleDao.insertAll(response.articles.map { it.toEntity() })
236	                remoteKeyDao.insert(
237	                    RemoteKey(
238	                        key = "articles",
239	                        nextPage = if (response.articles.isEmpty()) null else page + 1
240	                    )
241	                )
242	            }
243	
244	            MediatorResult.Success(endOfPaginationReached = response.articles.isEmpty())
245	        } catch (e: Exception) {
246	            MediatorResult.Error(e)
247	        }
248	    }
249	}
250	
251	// Usage in repository
252	@OptIn(ExperimentalPagingApi::class)
253	fun getOfflineArticles(): Flow<PagingData<ArticleEntity>> {
254	    return Pager(
255	        config = PagingConfig(pageSize = 20),
256	        remoteMediator = ArticleRemoteMediator(api, database),
257	        pagingSourceFactory = { database.articleDao().pagingSource() }
258	    ).flow
259	}
