286	### AsyncSequence-Based Pagination
287	
288	```swift
289	@Observable
290	class ArticleListViewModel {
291	    var articles: [Article] = []
292	    var isLoading = false
293	    var hasMore = true
294	    private var currentPage = 1
295	
296	    func loadNextPage() async {
297	        guard !isLoading, hasMore else { return }
298	        isLoading = true
299	        defer { isLoading = false }
300	
301	        do {
302	            let response = try await api.getArticles(page: currentPage, pageSize: 20)
303	            articles.append(contentsOf: response.articles)
304	            hasMore = !response.articles.isEmpty
305	            currentPage += 1
306	        } catch {
307	            // handle error
308	        }
309	    }
310	}
311	```
