314	
315	```swift
316	struct ArticleListView: View {
317	    @State private var viewModel = ArticleListViewModel()
318	
319	    var body: some View {
320	        List(viewModel.articles) { article in
321	            ArticleRow(article: article)
322	                .onAppear {
323	                    if article == viewModel.articles.last {
324	                        Task { await viewModel.loadNextPage() }
325	                    }
326	                }
327	        }
328	        .overlay {
329	            if viewModel.isLoading && viewModel.articles.isEmpty {
330	                ProgressView()
